```kotlin
fun main() {
    val numbers = listOf(1, 2, 3, 4, 5, 6)
    // معالجة كسولة لا تلمس سوى العناصر المطلوبة:
    val result = numbers.asSequence()
        .filter { println("Filter: $it"); it % 2 == 0 }
