    data class Success<T>(val data: T) : DomainResult<T, Nothing>
    data class Failure<E>(val error: E) : DomainResult<Nothing, E>
}

sealed interface PaymentError {
    data class InsufficientFunds(val balance: Long, val needed: Long) : PaymentError
    data object NetworkTimeout : PaymentError
