مثال يوضح الكود غير الآمن والحل التزامني المنضبط باستخدام Mutex في الكوروتينات:
```kotlin
// ❌ غير آمن تزامناً إطلاقاً رغم استخدام val:
val sharedList = mutableListOf<String>()

// ✅ الحل المعماري المنضبط باستخدام Mutex:
class SafeEventQueue {
    private val mutex = Mutex()
    private val _events = mutableListOf<String>()

    suspend fun addEvent(event: String) = mutex.withLock {
        _events.add(event)
    }

